package com.ruoyi.majorpilot.content;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.ruoyi.majorpilot.shared.*;
import java.util.*;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** Publication fixtures exist only in majorpilot_test and are removed by exact generated public IDs. */
@EnabledIfEnvironmentVariable(named="MP_RUN_MYSQL_TESTS",matches="true")
class TaskPublicationMySqlTest {
    static JdbcTemplate db;static TransactionTemplate tx;static final ObjectMapper JSON=new ObjectMapper();
    final List<String> ids=new ArrayList<>();final Map<String,TaskContentRepository.Bundle> fixtures=new HashMap<>();
    TaskContentRepository repository;TaskPublicationService service;PublishedTaskContentProvider provider;
    @BeforeAll static void database(){String url=System.getenv("MP_DB_URL");if(url==null||!url.startsWith("jdbc:mysql://127.0.0.1:13306/majorpilot?"))throw new IllegalStateException("Dedicated local database required");var source=new DriverManagerDataSource(url.replace("/majorpilot?","/majorpilot_test?"),System.getenv("MP_DB_USERNAME"),System.getenv("MP_DB_PASSWORD"));Flyway.configure().dataSource(source).locations("classpath:db/migration").cleanDisabled(true).load().migrate();db=new JdbcTemplate(source);tx=new TransactionTemplate(new DataSourceTransactionManager(source));}
    @BeforeEach void services(){assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM mp_task_version t JOIN mp_major m ON m.id=t.major_id WHERE m.code='AI'",Integer.class),"This bounded test never replaces someone else's content");repository=mock(TaskContentRepository.class);when(repository.get(anyString())).thenAnswer(call->{var b=fixtures.get(call.getArgument(0));if(b==null)throw new ApiException(404,"CONTENT_UNAVAILABLE");return b;});when(repository.bundles()).thenAnswer(call->List.copyOf(fixtures.values()));service=new TaskPublicationService(db,tx,repository,JSON,false);provider=new PublishedTaskContentProvider(db,repository,false);}
    @AfterEach void cleanup(){tx.executeWithoutResult(status->{for(String id:ids){db.update("DELETE FROM mp_sensitive_audit WHERE target_type='TASK_VERSION' AND target_public_id=?",id);db.update("DELETE FROM mp_task_version WHERE public_id=?",id);}});}
    TaskContentRepository.Bundle fixture(){String id=PublicIds.next();ids.add(id);ObjectNode manifest=(ObjectNode)new TaskContentRepository(JSON).get("demo-table/1.0.0/manifest.json").manifest();manifest.put("taskVersionId",id);manifest.put("contentKind","MAJOR");manifest.put("majorCode","AI");manifest.putNull("demoKey");manifest.put("versionCode","900.0."+System.nanoTime());((ObjectNode)manifest.path("estimatedMinutes")).put("minimum",45).put("maximum",60);ObjectNode review=(ObjectNode)manifest.path("review");review.put("kind","PROFESSIONAL").put("professionalReviewRequired",true);var checks=review.putArray("checkKeys");TaskManifestValidator.PROFESSIONAL_CHECKS.stream().sorted().forEach(checks::add);((ObjectNode)manifest.at("/operations/0")).put("engineType","RULES");TaskManifestValidator.validate(manifest);String path="test-publication/"+id.toLowerCase()+"/manifest.json";var b=new TaskContentRepository.Bundle(path,Secrets.hash(manifest.toString()),"d".repeat(64),manifest);fixtures.put(path,b);return b;}
    Map<String,Boolean> checks(){Map<String,Boolean> result=new HashMap<>();TaskManifestValidator.PROFESSIONAL_CHECKS.forEach(k->result.put(k,true));return result;}
    String id(TaskContentRepository.Bundle b){return b.manifest().path("taskVersionId").asText();}
    void review(TaskContentRepository.Bundle b){assertEquals("REVIEW",service.validate(new TaskPublicationService.Validate(b.path()),1,"unit-content").get("status"));}
    void publish(TaskContentRepository.Bundle b){service.publish(id(b),new TaskPublicationService.Publish(1L,checks(),"Synthetic test publication; no user-visible professional content"),1,"unit-content");}
    @Test void actualReviewGatesAndRevisionAreRequiredBeforePublishedThenRetiredRemainsPinned(){var b=fixture();review(b);assertEquals("CONTENT_REVIEW_REQUIRED",assertThrows(ApiException.class,()->service.publish(id(b),new TaskPublicationService.Publish(1L,Map.of(),"unit"),1,"unit")).code);assertEquals("REVISION_CONFLICT",assertThrows(ApiException.class,()->service.publish(id(b),new TaskPublicationService.Publish(0L,checks(),"unit"),1,"unit")).code);publish(b);assertEquals(id(b),provider.currentMajor("AI").taskVersionId());assertEquals("RETIRED",service.retire(id(b),new TaskPublicationService.Retire(2L,"Synthetic retirement"),1,"unit").get("status"));assertEquals("CONTENT_UNAVAILABLE",assertThrows(ApiException.class,()->provider.currentMajor("AI")).code);assertEquals(id(b),provider.pinned(id(b)).taskVersionId());assertEquals(3,db.queryForObject("SELECT COUNT(*) FROM mp_sensitive_audit WHERE target_public_id=?",Integer.class,id(b)));}
    @Test void newPublicationAtomicallyRetiresPriorAndCannotChangeItsPinnedHash(){var first=fixture();var second=fixture();review(first);publish(first);review(second);publish(second);assertEquals(id(second),provider.currentMajor("AI").taskVersionId());assertEquals(first.manifestSha256(),provider.pinned(id(first)).manifestSha256());assertEquals("RETIRED",db.queryForObject("SELECT status FROM mp_task_version WHERE public_id=?",String.class,id(first)));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM mp_task_version WHERE status='PUBLISHED' AND public_id IN (?,?)",Integer.class,id(first),id(second)));}
    @Test void changingExistingVersionHashIsRejectedWithoutMutation(){var b=fixture();review(b);fixtures.put(b.path(),new TaskContentRepository.Bundle(b.path(),"0".repeat(64),b.dataSha256(),b.manifest()));assertEquals("CONTENT_VERSION_IMMUTABLE",assertThrows(ApiException.class,()->service.validate(new TaskPublicationService.Validate(b.path()),1,"unit")).code);assertEquals(b.manifestSha256(),db.queryForObject("SELECT manifest_sha256 FROM mp_task_version WHERE public_id=?",String.class,id(b)));}
    @Test void auditFailureRollsBackPublicationAndNoOtherLaneIsTouched(){var b=fixture();review(b);assertThrows(RuntimeException.class,()->service.publish(id(b),new TaskPublicationService.Publish(1L,checks(),"unit"),1,"x".repeat(81)));assertEquals("REVIEW",db.queryForObject("SELECT status FROM mp_task_version WHERE public_id=?",String.class,id(b)));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM mp_sensitive_audit WHERE target_public_id=?",Integer.class,id(b)));}
    @Test void storedHashOrIdentityMismatchFailsClosedAndDemoDefaultIsDisabled(){var b=fixture();review(b);publish(b);db.update("UPDATE mp_task_version SET manifest_sha256=? WHERE public_id=?","0".repeat(64),id(b));assertEquals("CONTENT_INTEGRITY_FAILED",assertThrows(ApiException.class,()->provider.pinned(id(b))).code);assertEquals("DEMO_DISABLED",assertThrows(ApiException.class,()->provider.currentDemo("DEMO_TABLE")).code);assertEquals("CONTENT_UNAVAILABLE",assertThrows(ApiException.class,()->repository.get("../outside")).code);}
}
